47	#define lib_stream_putc(stream, ch) \
48	        ((FAR struct lib_outstream_s *)(stream))->putc( \
49	        (FAR struct lib_outstream_s *)(stream), ch)
50	#define lib_stream_puts(stream, buf, len) \
51	        ((FAR struct lib_outstream_s *)(stream))->puts( \
52	        (FAR struct lib_outstream_s *)(stream), buf, len)
53	#define lib_stream_eof(c) ((c) <= 0)
54	#define lib_stream_getc(stream) \
55	        ((FAR struct lib_instream_s *)(stream))->getc( \
56	        (FAR struct lib_instream_s *)(stream))
57	#define lib_stream_gets(stream, buf, len) \
58	        ((FAR struct lib_instream_s *)(stream))->gets( \
59	        (FAR struct lib_instream_s *)(stream), buf, len)
60	#define lib_stream_flush(stream) \
61	        ((FAR struct lib_outstream_s *)(stream))->flush( \
62	        (FAR struct lib_outstream_s *)(stream))
63	#define lib_stream_seek(stream, offset, whence) \
64	        ((FAR struct lib_sostream_s *)(stream))->seek( \
65	        (FAR struct lib_sostream_s *)(stream), offset, whence)
