74	
75	/* These are the generic representations of a streams used by the NuttX */
76	
77	struct lib_instream_s;
78	typedef CODE int     (*lib_getc_t)(FAR struct lib_instream_s *self);
79	typedef CODE ssize_t (*lib_gets_t)(FAR struct lib_instream_s *self,
80	                                   FAR void *buf, size_t len);
81	
82	struct lib_outstream_s;
83	typedef CODE void    (*lib_putc_t)(FAR struct lib_outstream_s *self, int ch);
84	typedef CODE ssize_t (*lib_puts_t)(FAR struct lib_outstream_s *self,
85	                                   FAR const void *buf, size_t len);
86	typedef CODE int     (*lib_flush_t)(FAR struct lib_outstream_s *self);
87	
88	struct lib_instream_s
89	{
90	  off_t                  nget;    /* Total number of characters gotten.  Written
91	                                   * by get method, readable by user */
92	  lib_getc_t             getc;    /* Get one character from the instream */
93	  lib_gets_t             gets;    /* Get the string from the instream */
94	};
95	
96	struct lib_outstream_s
97	{
98	  off_t                  nput;    /* Total number of characters put.  Written
99	                                   * by put method, readable by user */
100	  lib_putc_t             putc;    /* Put one character to the outstream */
101	  lib_puts_t             puts;    /* Writes the string to the outstream */
102	  FAR void              *none;    /* Placeholder */
103	  lib_flush_t            flush;   /* Flush any buffered characters in the outstream */
104	};
105	
106	/* Seek-able streams */
107	
108	struct lib_sistream_s;
109	typedef CODE int     (*lib_sigetc_t)(FAR struct lib_sistream_s *self);
110	typedef CODE ssize_t (*lib_sigets_t)(FAR struct lib_sistream_s *self,
111	                                     FAR void *buf, size_t len);
112	typedef CODE off_t   (*lib_siseek_t)(FAR struct lib_sistream_s *self,
113	                                     off_t offset, int whence);
114	
115	struct lib_sostream_s;
116	typedef CODE void    (*lib_soputc_t)(FAR struct lib_sostream_s *self,
117	                                     int ch);
118	typedef CODE ssize_t (*lib_soputs_t)(FAR struct lib_sostream_s *self,
119	                                     FAR const void *buf, size_t len);
120	typedef CODE int     (*lib_soflush_t)(FAR struct lib_sostream_s *self);
121	typedef CODE off_t   (*lib_soseek_t)(FAR struct lib_sostream_s *self,
122	                                     off_t offset, int whence);
123	
124	struct lib_sistream_s
125	{
126	  off_t                  nget;    /* Total number of characters gotten.  Written
127	                                   * by get method, readable by user */
128	  lib_sigetc_t           getc;    /* Get one character from the instream */
129	  lib_sigets_t           gets;    /* Get the string from the instream */
130	  lib_siseek_t           seek;    /* Seek to a position in the instream */
131	};
132	
133	struct lib_sostream_s
134	{
135	  off_t                  nput;    /* Total number of characters put.  Written
136	                                   * by put method, readable by user */
137	  lib_soputc_t           putc;    /* Put one character to the outstream */
138	  lib_soputs_t           puts;    /* Writes the string to the outstream */
139	  lib_soseek_t           seek;    /* Seek a position in the output stream */
140	  lib_soflush_t          flush;   /* Flush any buffered characters in the outstream */
141	};
