367	/****************************************************************************
368	 * Name: lib_meminstream, lib_memoutstream, lib_memsistream, lib_memsostream
369	 *
370	 * Description:
371	 *   Initializes a stream for use with a fixed-size memory buffer.
372	 *   Defined in lib/stdio/lib_meminstream.c and lib/stdio/lib_memoutstream.c.
373	 *   Seekable versions are defined in lib/stdio/lib_memsistream.c and
374	 *   lib/stdio/lib_memsostream.c.
375	 *
376	 * Input Parameters:
377	 *   stream    - User allocated, uninitialized instance of stream struct
378	 *               to be initialized.
379	 *   bufstart  - Address of the beginning of the fixed-size memory buffer
380	 *   buflen    - Size of the fixed-sized memory buffer in bytes
381	 *
382	 * Returned Value:
383	 *   None (User allocated instance initialized).
384	 *
385	 ****************************************************************************/
386	
387	void lib_meminstream(FAR struct lib_meminstream_s *stream,
388	                     FAR const char *bufstart, size_t buflen);
389	void lib_memoutstream(FAR struct lib_memoutstream_s *stream,
390	                      FAR char *bufstart, size_t buflen);
391	void lib_memsistream(FAR struct lib_memsistream_s *stream,
392	                     FAR const char *bufstart, size_t buflen);
393	void lib_memsostream(FAR struct lib_memsostream_s *stream,
394	                     FAR char *bufstart, size_t buflen);
395	
