38	int fputc_unlocked(int c, FAR FILE *stream)
39	{
40	  unsigned char buf = (unsigned char)c;
41	  int ret;
42	
43	  ret = lib_fwrite_unlocked(&buf, 1, stream);
44	  if (ret > 0)
45	    {
46	      /* Flush the buffer if a newline is output */
47	
48	      if (c == '\n' && (stream->fs_flags & __FS_FLAG_LBF) != 0)
49	        {
50	          ret = lib_fflush_unlocked(stream);
51	          if (ret < 0)
52	            {
53	              return EOF;
54	            }
55	        }
56	
57	      return c;
58	    }
59	  else
60	    {
61	      return EOF;
62	    }
63	}
64	
65	int fputc(int c, FAR FILE *stream)
66	{
67	  int ret;
68	
69	  flockfile(stream);
70	  ret = fputc_unlocked(c, stream);
71	  funlockfile(stream);
72	
73	  return ret;
74	}
