43	
44	/****************************************************************************
45	 * Name: lib_fwrite
46	 ****************************************************************************/
47	
48	ssize_t lib_fwrite_unlocked(FAR const void *ptr, size_t count,
49	                            FAR FILE *stream)
50	#ifndef CONFIG_STDIO_DISABLE_BUFFERING
51	{
52	  FAR const char *start = ptr;
53	  FAR const char *src   = ptr;
54	  ssize_t ret = ERROR;
55	  size_t gulp_size;
56	
57	  /* Make sure that writing to this stream is allowed */
58	
59	  if (stream == NULL)
60	    {
61	      set_errno(EBADF);
62	      return ret;
63	    }
64	
65	  /* Check if write access is permitted */
66	
67	  if ((stream->fs_oflags & O_WROK) == 0)
68	    {
69	      set_errno(EBADF);
70	      goto errout;
71	    }
72	
73	  /* If there is no I/O buffer, then output data immediately */
74	
75	  if (stream->fs_bufstart == NULL)
76	    {
77	      if (stream->fs_iofunc.write != NULL)
78	        {
79	          ret = stream->fs_iofunc.write(stream->fs_cookie, ptr, count);
80	        }
81	      else
82	        {
83	          ret = _NX_WRITE((int)(intptr_t)stream->fs_cookie, ptr, count);
84	        }
85	
86	      if (ret < 0)
87	        {
88	          _NX_SETERRNO(ret);
89	          ret = ERROR;
90	        }
91	
92	      goto errout;
93	    }
94	
95	  /* If the buffer is currently being used for read access, then
96	   * discard all of the read-ahead data.  We do not support concurrent
97	   * buffered read/write access.
98	   */
99	
100	  if (lib_rdflush_unlocked(stream) < 0)
101	    {
102	      goto errout;
103	    }
104	
105	  /* Determine the number of bytes left in the buffer */
106	
107	  gulp_size = stream->fs_bufend - stream->fs_bufpos;
108	  if (gulp_size != CONFIG_STDIO_BUFFER_SIZE || count < gulp_size)
109	    {
110	      if (gulp_size > count)
111	        {
112	          /* Yes, clip the gulp to the size of the user data */
113	
114	          gulp_size = count;
115	        }
116	
117	      /* Adjust the number of bytes remaining to be transferred
118	       * on the next pass through the loop (might be zero).
119	       */
120	
121	      count -= gulp_size;
122	
123	      /* Transfer the data into the buffer */
124	
125	      memcpy(stream->fs_bufpos, src, gulp_size);
126	      stream->fs_bufpos += gulp_size;
127	      src += gulp_size;
128	
129	      /* Is the buffer full? */
130	
131	      if (stream->fs_bufpos >= stream->fs_bufend)
132	        {
133	          /* Flush the buffered data to the IO stream */
134	
135	          int bytes_buffered = lib_fflush_unlocked(stream);
136	          if (bytes_buffered < 0)
137	            {
138	              goto errout;
139	            }
140	        }
141	
142	      /* POSIX: in line-buffered mode (_IOLBF), flush if any newline
143	       * appears in the data written so far by this fwrite call.
144	       * We check the bytes from 'start' to 'src' (the data we've
145	       * consumed so far from the user's buffer).
146	       */
147	
148	      else if (stream->fs_flags & __FS_FLAG_LBF)
149	        {
150	          if (memchr(start, '\n', src - start) != NULL)
151	            {
152	              int bytes_buffered = lib_fflush_unlocked(stream);
153	              if (bytes_buffered < 0)
154	                {
155	                  goto errout;
156	                }
157	            }
158	        }
159	    }
160	
161	  if (count >= CONFIG_STDIO_BUFFER_SIZE)
162	    {
163	      if (stream->fs_iofunc.write != NULL)
164	        {
165	          ret = stream->fs_iofunc.write(stream->fs_cookie, src, count);
166	        }
167	      else
168	        {
169	          ret = _NX_WRITE((int)(intptr_t)stream->fs_cookie, src, count);
170	        }
171	
172	      if (ret < 0)
173	        {
174	          _NX_SETERRNO(ret);
175	          ret = ERROR;
176	          goto errout;
177	        }
178	
179	      src += ret;
180	    }
181	  else if (count > 0)
182	    {
183	      memcpy(stream->fs_bufpos, src, count);
184	      stream->fs_bufpos += count;
185	      src += count;
186	
187	      /* If line-buffered, check whether data written so
188	       * far contains newline. (This covers
189	       * the tail-copy path.)
190	       */
191	
192	      if (stream->fs_flags & __FS_FLAG_LBF)
193	        {
194	          if (memchr(start, '\n', src - start) != NULL)
195	            {
196	              int bytes_buffered = lib_fflush_unlocked(stream);
197	              if (bytes_buffered < 0)
198	                {
199	                  goto errout;
200	                }
201	            }
202	        }
203	    }
204	
205	  /* Return the number of bytes written */
206	
207	  ret = (uintptr_t)src - (uintptr_t)start;
208	
209	errout:
210	  if (ret < 0)
211	    {
212	      stream->fs_flags |= __FS_FLAG_ERROR;
213	    }
214	
215	  return ret;
216	}
217	#else
218	{
219	  ssize_t ret;
220	  if (stream->fs_iofunc.write != NULL)
221	    {
222	      ret = stream->fs_iofunc.write(stream->fs_cookie, ptr, count);
223	    }
224	  else
225	    {
226	      ret = _NX_WRITE((int)(intptr_t)stream->fs_cookie, ptr, count);
227	    }
228	
229	  if (ret < 0)
230	    {
231	      stream->fs_flags |= __FS_FLAG_ERROR;
232	      _NX_SETERRNO(ret);
233	    }
234	
235	  return ret;
236	}
237	#endif /* CONFIG_STDIO_DISABLE_BUFFERING */
238	
239	ssize_t lib_fwrite(FAR const void *ptr, size_t count, FAR FILE *stream)
240	{
241	  ssize_t ret;
242	
243	  flockfile(stream);
244	  ret = lib_fwrite_unlocked(ptr, count, stream);
245	  funlockfile(stream);
246	
247	  return ret;
248	}
