120	      nxrmutex_init(&filep->fs_lock);
121	
122	#ifdef CONFIG_FDSAN
123	      android_fdsan_exchange_owner_tag(fd, 0,
124	          android_fdsan_create_owner_tag(ANDROID_FDSAN_OWNER_TYPE_FILE,
125	                                        (uintptr_t)filep));
126	#endif
127	    }
128	  else
129	    {
130	      filep = &list->sl_std[fd];
131	    }
132	
133	#if !defined(CONFIG_STDIO_DISABLE_BUFFERING) && CONFIG_STDIO_BUFFER_SIZE > 0
134	  /* Set up pointers */
135	
136	  filep->fs_bufstart = filep->fs_buffer;
137	  filep->fs_bufend   = filep->fs_bufstart + CONFIG_STDIO_BUFFER_SIZE;
138	  filep->fs_bufpos   = filep->fs_bufstart;
139	  filep->fs_bufread  = filep->fs_bufstart;
140	  filep->fs_flags    = __FS_FLAG_UBF; /* Fake setvbuf and fclose */
141	#if CONFIG_NUNGET_CHARS > 0
142	  /* clear any characters pushed back onto the stream */
143	
144	  filep->fs_nungotten = 0;
145	#endif
146	#  ifdef CONFIG_STDIO_LINEBUFFER
147	  /* Setup buffer flags */
148	
149	  if ((oflags & O_WRONLY) != 0 && isatty(fd))
150	    {
151	      filep->fs_flags |= __FS_FLAG_LBF; /* Enable LBF only for terminals */
152	    }
153	
154	#  endif /* CONFIG_STDIO_LINEBUFFER */
155	#endif /* !CONFIG_STDIO_DISABLE_BUFFERING && CONFIG_STDIO_BUFFER_SIZE > 0 */
156	
157	  /* Save the file description and open flags.  Setting the
158	   * file descriptor locks this stream.
159	   */
160	
161	  filep->fs_cookie   = (FAR void *)(intptr_t)fd;
162	  filep->fs_oflags   = oflags;
163	
164	  /* Assign custom callbacks to NULL. */
165	
166	  filep->fs_iofunc.read  = NULL;
167	  filep->fs_iofunc.write = NULL;
168	  filep->fs_iofunc.seek  = NULL;
169	  filep->fs_iofunc.close = NULL;
170	
171	  return filep;
172	}
