174	/****************************************************************************
175	 * Name: fopen
176	 ****************************************************************************/
177	
178	FAR FILE *fopen(FAR const char *path, FAR const char *mode)
179	{
180	  FAR FILE *filep = NULL;
181	  int oflags;
182	  int fd;
183	
184	  /* Map the open mode string to open flags */
185	
186	  oflags = lib_mode2oflags(mode);
187	  if (oflags < 0)
188	    {
189	      return NULL;
190	    }
191	
192	  /* Open the file */
193	
194	  fd = open(path, oflags, 0666);
195	
196	  /* If the open was successful, then call fdopen() using the file
197	   * descriptor returned by open.  If open failed, then just return the
198	   * NULL stream -- open() has already set the errno.
199	   */
200	
201	  if (fd >= 0)
202	    {
203	      filep = fdopen(fd, mode);
204	      if (filep == NULL)
205	        {
206	          /* Don't forget to close the file descriptor if any other
207	           * failures are reported by fdopen().
208	           */
209	
210	          close(fd);
211	        }
212	    }
213	
214	  return filep;
215	}
