217	/****************************************************************************
218	 * Name: lib_mode2oflags
219	 ****************************************************************************/
220	
221	int lib_mode2oflags(FAR const char *mode)
222	{
223	  unsigned int state;
224	  int oflags;
225	
226	  /* Verify that a mode string was provided.  */
227	
228	  DEBUGASSERT(mode);
229	
230	  /* Parse the mode string to determine the corresponding open flags */
231	
232	  state  = MODE_NONE;
233	  oflags = 0;
234	
235	  for (; *mode; mode++)
236	    {
237	      switch (*mode)
238	        {
239	          /* Open for read access ("r{m|b|x|+}") */
240	
241	          case 'r' :
242	            if (state == MODE_NONE)
243	              {
244	                /* Open for read access */
245	
246	                oflags = O_RDOK | O_TEXT;
247	                state  = MODE_R;
248	              }
249	            else
250	              {
251	                goto errout;
252	              }
253	            break;
254	
255	          /* Open for write access ("w{b|x|+}") */
256	
257	          case 'w' :
258	            if (state == MODE_NONE)
259	              {
260	                /* Open for write access, truncating any existing file */
261	
262	                oflags = O_WROK | O_CREAT | O_TRUNC | O_TEXT;
263	                state  = MODE_W;
264	              }
265	            else
266	              {
267	                goto errout;
268	              }
269	            break;
270	
271	          /* Open for write/append access ("a{b|x|+}") */
272	
273	          case 'a' :
274	            if (state == MODE_NONE)
275	              {
276	                /* Write to the end of the file */
277	
278	                oflags = O_WROK | O_CREAT | O_APPEND | O_TEXT;
279	                state  = MODE_A;
280	              }
281	            else
282	              {
283	                goto errout;
284	              }
285	            break;
286	
287	          /* Open for update access ("{r|w|a|b|x}+") */
288	
289	          case '+' :
290	            switch (state & MODE_MASK)
291	              {
292	                case MODE_R:
293	                  {
294	                    /* Retain any binary and exclusive mode selections */
295	
296	                    oflags &= FLAG_KEEP;
297	
298	                    /* Open for read/write access */
299	
300	                    oflags |= O_RDWR;
301	                 }
302	                 break;
303	
304	                case MODE_W:
305	                  {
306	                    /* Retain any binary and exclusive mode selections */
307	
308	                    oflags &= FLAG_KEEP;
309	
310	                    /* Open for write read/access, truncating any existing
311	                     * file.
312	                     */
313	
314	                    oflags |= O_RDWR | O_CREAT | O_TRUNC;
315	                  }
316	                  break;
317	
318	                case MODE_A:
319	                  {
320	                    /* Retain any binary and exclusive mode selections */
321	
322	                    oflags &= FLAG_KEEP;
323	
324	                    /* Read from the beginning of the file; write to the
325	                     * end,
326	                     */
327	
328	                    oflags |= O_RDWR | O_CREAT | O_APPEND;
329	                  }
330	                  break;
331	
332	                default:
333	                  goto errout;
334	              }
335	            break;
336	
337	          /* Attempt to access the file using mmap. */
338	
339	          case 'm' :
340	            if (state != MODE_R)
341	              {
342	                goto errout;
343	              }
344	            break;
345	
346	          /* Open for binary access ("{r|w|a|x|+}b") */
347	
348	          case 'b' :
349	            if ((state & MODE_MASK) != MODE_NONE)
350	              {
351	                /* The file is opened in binary mode */
352	
353	                oflags &= ~O_TEXT;
354	              }
355	            else
356	              {
357	                goto errout;
358	              }
359	            break;
360	
361	          /* Open for close on execute */
362	
363	          case 'e' :
364	            if ((state & MODE_MASK) != MODE_NONE)
365	              {
366	                /* The file will be closed on execute */
367	
368	                oflags |= O_CLOEXEC;
369	              }
370	            else
371	              {
372	                goto errout;
373	              }
374	            break;
375	
376	          /* Open for exclusive access ("{r|w|a|b|+}x") */
377	
378	          case 'x' :
379	            if ((state & MODE_MASK) != MODE_NONE)
380	              {
381	                /* The file is opened in exclusive mode */
382	
383	                oflags |= O_EXCL;
384	              }
385	            else
386	              {
387	                goto errout;
388	              }
389	            break;
390	
391	          /* Open for text (translated) access ("{r|w|a|x|+}t") */
392	
393	          case 't' :
394	            if ((state & MODE_MASK) != MODE_NONE)
395	              {
396	                /* The file is opened in text mode */
397	
398	                oflags |= O_TEXT;
399	              }
400	            else
401	              {
402	                goto errout;
403	              }
404	            break;
405	
406	          /* Unrecognized or unsupported mode */
407	
408	          default:
409	            goto errout;
410	        }
411	    }
412	
413	  return oflags;
414	
415	/* Both fopen and fdopen should fail with errno == EINVAL if the mode
416	 * string is invalid.
417	 */
418	
419	errout:
420	  set_errno(EINVAL);
421	  return ERROR;
422	}
